// sensors/<device-id>/<measurement> and inference/<device-id>/result, also
// under sandbox/, to one line of InfluxDB line protocol. Output 1 goes to the
// raw_telemetry bucket, output 2 (sandbox/ topics) to the sandbox bucket. Each
// line carries its own timestamp, so the join nodes after this one can batch
// lines into a single write.
//
// Payloads: a JSON object; nested objects and arrays are flattened
// ({"accel": {"x": 1}} becomes accel_x, [1, 2] becomes name_0, name_1). A bare
// number, boolean or text (23.5, true, "on") becomes the "value" field.
// "ts", "timestamp" or "time" (epoch s, ms, µs or ns, or an ISO 8601 string)
// is the reading's time; without one, the time it arrived here.

var token = env.get("INFLUXDB_TOKEN");
var org = env.get("INFLUXDB_ORG");
if (!token || !org) {
    node.error("INFLUXDB_TOKEN and INFLUXDB_ORG env vars must be set", msg);
    return null;
}

var TIME_KEYS = ["ts", "timestamp", "time"];
// Earliest believable reading: devices without a clock send 0 or their uptime
var MIN_TIME = Date.UTC(2000, 0, 1);
var MAX_DEPTH = 4;

// Line protocol escaping (newlines would start a new line, so drop them)
function clean(s) { return String(s).replace(/[\r\n]+/g, " "); }
function escMeasurement(s) { return clean(s).replace(/[\\, ]/g, "\\$&"); }
function escKey(s) { return clean(s).replace(/[\\,= ]/g, "\\$&"); }
function escString(s) { return '"' + clean(s).replace(/[\\"]/g, "\\$&") + '"'; }

// Epoch milliseconds from s, ms, µs or ns (told apart by size), or ISO 8601
function toMillis(v) {
    if (typeof v === "string" && /^\s*-?\d+(\.\d+)?\s*$/.test(v)) v = Number(v);
    if (typeof v === "number") {
        if (!isFinite(v)) return NaN;
        var abs = Math.abs(v);
        if (abs < 1e11) return Math.round(v * 1000);
        if (abs < 1e14) return Math.round(v);
        if (abs < 1e17) return Math.round(v / 1e3);
        return Math.round(v / 1e6);
    }
    if (typeof v === "string") return Date.parse(v);
    return NaN;
}

// Warns once per device, not on every reading
function warnOnce(device, text) {
    var warned = context.get("warnedTime") || {};
    if (warned[device]) return;
    warned[device] = true;
    context.set("warnedTime", warned);
    node.warn(text);
}

function addFields(obj, prefix, depth, fields, skip) {
    for (var key in obj) {
        if (!Object.prototype.hasOwnProperty.call(obj, key)) continue;
        if (depth === 0 && skip.indexOf(key) !== -1) continue;
        var val = obj[key];
        var name = prefix ? prefix + "_" + key : key;
        if (val !== null && typeof val === "object") {
            if (depth < MAX_DEPTH) addFields(val, name, depth + 1, fields, skip);
        } else if (typeof val === "number") {
            if (isFinite(val)) fields.push(escKey(name) + "=" + val);
        } else if (typeof val === "string") {
            fields.push(escKey(name) + "=" + escString(val));
        } else if (typeof val === "boolean") {
            fields.push(escKey(name) + "=" + (val ? "true" : "false"));
        }
    }
}

var sandbox = /^sandbox\//.test(msg.topic || "");
var topic = (msg.topic || "").replace(/^sandbox\//, "");
var where = sandbox ? "sandbox/" : "";

// Payload: JSON, or a bare value
var data = msg.payload;
if (Buffer.isBuffer(data)) data = data.toString();
if (typeof data === "string") {
    var text = data.trim();
    try {
        data = JSON.parse(text);
    } catch (err) {
        if (text === "" || /^[\[{"]/.test(text)) {
            node.warn("Invalid payload on " + msg.topic + ": not valid JSON");
            return null;
        }
        data = text;
    }
}
if (typeof data === "number" || typeof data === "boolean" || typeof data === "string") {
    data = { value: data };
}
if (!data || typeof data !== "object" || Array.isArray(data)) {
    node.warn("Invalid payload on " + msg.topic + ": expected a JSON object or a single value");
    return null;
}
// Already stored by p4n4-api (POST /api/v1/telemetry), with the device's own
// timestamp: storing it again would duplicate the reading
if (data._stored_by === "p4n4-api") return null;

var parts = topic.split("/");
var measurement, tags = {};
if (parts[0] === "sensors") {
    // sensors/<device-id>/<measurement>: the topic names the device and sensor
    if (parts.length !== 3 || !parts[1] || !parts[2]) {
        node.warn("Ignored " + msg.topic + ": expected " + where + "sensors/<device-id>/<measurement>");
        return null;
    }
    measurement = "sensor_data";
    tags.device = parts[1];
    tags.sensor = parts[2];
} else if (parts[0] === "inference") {
    // inference/<device-id>/result: the topic names the device
    if (parts.length !== 3 || !parts[1] || parts[2] !== "result") {
        node.warn("Ignored " + msg.topic + ": expected " + where + "inference/<device-id>/result");
        return null;
    }
    measurement = "inference";
    tags.device = parts[1];
    if (data.model) tags.model = data.model;
} else {
    node.warn("Unknown topic: " + msg.topic);
    return null;
}

// The reading's own time, if it has a believable one
var now = Date.now();
var time = now;
var skip = ["device", "model", "_stored_by"].concat(TIME_KEYS);
if (sandbox) skip.push("sandbox");
for (var i = 0; i < TIME_KEYS.length; i++) {
    if (data[TIME_KEYS[i]] === undefined) continue;
    var t = toMillis(data[TIME_KEYS[i]]);
    if (t >= MIN_TIME && t <= now + 86400000) {
        time = t;
    } else {
        warnOnce(tags.device, "Ignored " + TIME_KEYS[i] + "=" + JSON.stringify(data[TIME_KEYS[i]]) +
            " from " + tags.device + ": not a time between 2000 and tomorrow; using the arrival time");
    }
    break;
}

var fields = [];
addFields(data, "", 0, fields, skip);
if (fields.length === 0) return null;

var line = escMeasurement(measurement);
Object.keys(tags).sort().forEach(function (k) {
    var v = clean(tags[k]);
    if (v !== "") line += "," + escKey(k) + "=" + escKey(v);
});
line += " " + fields.join(",") + " " + time;

var bucket = sandbox
    ? env.get("INFLUXDB_SANDBOX_BUCKET") || "sandbox"
    : env.get("INFLUXDB_BUCKET") || "raw_telemetry";
msg.payload = line;
msg.url = "http://influxdb:8086/api/v2/write?org=" + encodeURIComponent(org) +
    "&bucket=" + encodeURIComponent(bucket) + "&precision=ms";
msg.headers = {
    "Authorization": "Token " + token,
    "Content-Type": "text/plain; charset=utf-8"
};
return sandbox ? [null, msg] : [msg, null];

try {
    var token = env.get("INFLUXDB_TOKEN");
    var org = env.get("INFLUXDB_ORG");
    var bucket = env.get("INFLUXDB_BUCKET_AI_EVENTS") || "ai_events";
    if (!token || !org) {
        node.error("INFLUXDB_TOKEN and INFLUXDB_ORG env vars must be set", msg);
        return null;
    }

    // Tags stay within the question sets' menus: anything else would grow series
    // cardinality with free text, so the point is dropped
    var TAG = /^[a-z0-9_-]{1,64}$/;
    function clean(s) { return String(s).replace(/[\r\n]+/g, " "); }
    function escString(s) { return '"' + clean(s).replace(/[\\"]/g, "\\$&") + '"'; }
    function isInt(v) { return typeof v === "number" && isFinite(v) && Math.floor(v) === v; }

    var d = msg.payload;
    var set = (msg.topic || "").split("/")[2];
    if (!d || typeof d !== "object" || Array.isArray(d) || !d.answers || typeof d.answers !== "object") {
        node.warn("Ignored " + msg.topic + ": expected a decision object with answers");
        return null;
    }
    if (d.set !== set) {
        node.warn("Ignored " + msg.topic + ": its set is " + JSON.stringify(d.set));
        return null;
    }
    var ts = Date.parse(d.ts);
    if (isNaN(ts)) ts = Date.now();

    var lines = [];
    Object.keys(d.answers).forEach(function (question) {
        var a = d.answers[question] || {};
        var tags = { caller: d.caller, checkpoint: d.checkpoint, choice: a.choice, question: question, set: d.set };
        var bad = Object.keys(tags).filter(function (k) { return !TAG.test(String(tags[k])); });
        if (bad.length) {
            node.warn("Dropped a system1_decision point from " + msg.topic + ": tags " + bad.join(", ") +
                " must match " + TAG);
            return;
        }
        if (typeof a.confidence !== "number" || !isFinite(a.confidence)) {
            node.warn("Dropped a system1_decision point from " + msg.topic + ": no confidence");
            return;
        }
        var fields = [
            "confidence=" + a.confidence,
            "abstain=" + (a.abstain === true),
            "used=" + (d.used === true),
        ];
        if (isInt(d.set_version)) fields.push("set_version=" + d.set_version + "i");
        if (isInt(d.latency_ms)) fields.push("latency_ms=" + d.latency_ms + "i");
        ["id", "revision", "subject", "state_sha256"].forEach(function (k) {
            if (d[k] !== undefined && d[k] !== null) fields.push(k + "=" + escString(d[k]));
        });
        var line = "system1_decision";
        Object.keys(tags).sort().forEach(function (k) { line += "," + k + "=" + tags[k]; });
        lines.push(line + " " + fields.join(",") + " " + ts);
    });

    if (lines.length === 0) return null;
    msg.payload = lines.join("\n");
    msg.url = "http://influxdb:8086/api/v2/write?org=" + encodeURIComponent(org) +
        "&bucket=" + encodeURIComponent(bucket) + "&precision=ms";
    msg.headers = { "Authorization": "Token " + token, "Content-Type": "text/plain" };
    return msg;
} catch (err) {
    node.error("Format error: " + err.message, msg);
    return null;
}

// p4n4-system1: runs a System 1 question set on msg.payload, the state.
// The set is msg.set, else the subflow's SET property. On any failure the
// subflow sets msg.error, sends a null payload and never throws (F-0.2.2).
var TAG = /^[a-z0-9_-]{1,64}$/;
var set = String(msg.set || env.get("SET") || "");
var caller = String(env.get("CALLER") || "node-red");
var key = env.get("SYSTEM1_API_KEY");
function failed(text) {
    msg.error = text;
    msg.payload = null;
    return [null, msg];
}
if (!TAG.test(set)) return failed("system1: msg.set or the SET property must name a question set");
if (!TAG.test(caller)) return failed("system1: CALLER must match " + TAG);
if (!key) return failed("system1: SYSTEM1_API_KEY is not set in Node-RED's environment");
if (msg.payload === undefined || msg.payload === null) return failed("system1: msg.payload must hold the state");

msg._system1 = { set: set, caller: caller, subject: String(msg.subject || ""), started: Date.now() };
msg.url = "http://p4n4-system1:8000/v1/sets/" + set;
msg.method = "POST";
msg.headers = { "Authorization": "Bearer " + key, "Content-Type": "application/json" };
msg.requestTimeout = Number(env.get("TIMEOUT_MS")) || 5000;
msg.payload = JSON.stringify({ state: msg.payload });
delete msg.error;
return [msg, null];

// The answers, each with its abstain flag; a decision log message for every
// answered request (docs: decisions/system1.md §6.7)
function uuid() {
    return "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, function (c) {
        var r = Math.random() * 16 | 0;
        return (c === "x" ? r : (r & 0x3 | 0x8)).toString(16);
    });
}
var ctx = msg._system1 || {};
delete msg._system1;
delete msg.headers;
delete msg.url;
delete msg.method;
delete msg.requestTimeout;
var res = msg.payload;
if (msg.statusCode !== 200 || !res || typeof res !== "object" || !res.answers || !res.set) {
    var detail = res && typeof res === "object" && res.detail ? res.detail : String(res || "").slice(0, 200);
    msg.error = "system1: " + ctx.set + " answered " + msg.statusCode + ": " + JSON.stringify(detail);
    msg.payload = null;
    return [msg, null];
}
var used = Object.keys(res.answers).some(function (q) { return res.answers[q].abstain === false; });
var snapshot = /\/snapshots\/([0-9a-f]{40})/.exec((res.routing || {}).repo || "");
var answers = {};
Object.keys(res.answers).forEach(function (q) {
    var a = res.answers[q];
    answers[q] = { choice: a.choice, confidence: a.confidence, abstain: a.abstain };
});
var decision = {
    id: uuid(),
    ts: new Date().toISOString(),
    set: res.set.name,
    set_version: res.set.version,
    checkpoint: (res.routing || {}).model || "",
    revision: snapshot ? snapshot[1].slice(0, 12) : "",
    caller: ctx.caller,
    subject: ctx.subject,
    state_sha256: res.state_sha256 || "",
    latency_ms: Date.now() - ctx.started,
    answers: answers,
    // The subflow can't know what its caller does next: an answer it hands on
    // unabstained counts as used
    used: used,
};
msg.system1 = { id: decision.id, set: res.set.name, version: res.set.version, used: used };
return [msg, { topic: "system1/decisions/" + res.set.name, payload: JSON.stringify(decision) }];

// Refused connections, timeouts and other request errors: the same contract
var ctx = msg._system1 || {};
var text = msg.error && msg.error.message ? msg.error.message : String(msg.error || "request failed");
["_system1", "headers", "url", "method", "requestTimeout"].forEach(function (k) { delete msg[k]; });
msg.error = "system1: " + ctx.set + " request failed: " + text.slice(0, 200);
msg.payload = null;
return msg;

try {
    var token = env.get("INFLUXDB_TOKEN");
    var org = env.get("INFLUXDB_ORG");
    var bucket = env.get("INFLUXDB_BUCKET_AI_EVENTS") || "ai_events";
    if (!token || !org) {
        node.error("INFLUXDB_TOKEN and INFLUXDB_ORG env vars must be set", msg);
        return null;
    }
    var TAG = /^[a-z0-9_-]{1,64}$/;
    function clean(s) { return String(s).replace(/[\r\n]+/g, " "); }
    function escString(s) { return '"' + clean(s).replace(/[\\"]/g, "\\$&") + '"'; }
    function isInt(v) { return typeof v === "number" && isFinite(v) && Math.floor(v) === v; }

    var f = msg.payload;
    var set = (msg.topic || "").split("/")[2];
    if (!f || typeof f !== "object" || Array.isArray(f) || f.set !== set || typeof f.id !== "string") {
        node.warn("Ignored " + msg.topic + ": expected a feedback object for set " + JSON.stringify(set));
        return null;
    }
    var tags = { caller: f.caller, choice: f.choice, expected: f.expected, question: f.question, set: f.set };
    var bad = Object.keys(tags).filter(function (k) { return !TAG.test(String(tags[k])); });
    if (bad.length) {
        node.warn("Dropped a system1_feedback point from " + msg.topic + ": tags " + bad.join(", ") +
            " must match " + TAG);
        return null;
    }
    var ts = Date.parse(f.ts);
    if (isNaN(ts)) ts = Date.now();
    var abstain = f.abstain === true;
    var fields = [
        "abstain=" + abstain,
        // The person kept what System 1 answered (an abstained answer never agrees)
        "agreed=" + (!abstain && f.choice === f.expected),
        "id=" + escString(f.id),
    ];
    if (isInt(f.set_version)) fields.push("set_version=" + f.set_version + "i");
    var line = "system1_feedback";
    Object.keys(tags).sort().forEach(function (k) { line += "," + k + "=" + tags[k]; });

    var write = {
        payload: line + " " + fields.join(",") + " " + ts,
        url: "http://influxdb:8086/api/v2/write?org=" + encodeURIComponent(org) +
            "&bucket=" + encodeURIComponent(bucket) + "&precision=ms",
        headers: { "Authorization": "Token " + token, "Content-Type": "text/plain" },
    };
    // A site that opts in sends the state too: it is kept as an evaluation
    // example in Node-RED's volume, never in InfluxDB (p4n4 ai system1 feedback)
    var keep = null;
    if (f.state !== undefined) {
        keep = { filename: "/data/system1/feedback/" + f.set + ".jsonl", payload: JSON.stringify(f) };
    }
    return [write, keep];
} catch (err) {
    node.error("Format error: " + err.message, msg);
    return null;
}
